CREATE OR REPLACE FUNCTION public.metrics_contract_factor(_contract uuid,_scope jsonb) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(sum(cu.annual_rent_excl_vat)/nullif(c.annual_rent_excl_vat,0),0) FROM public.contracts c JOIN public.contract_units cu ON cu.contract_id=c.id JOIN public.metrics_unit_scope u ON u.id=cu.unit_id WHERE c.id=_contract AND public.metrics_scope_match(u,_scope) GROUP BY c.annual_rent_excl_vat $$;
CREATE OR REPLACE FUNCTION public.metrics_collected_rows(_scope jsonb) RETURNS TABLE(id uuid,receipt_no text,paid_at timestamptz,status text,amount_excl_vat numeric,vat_amount numeric,amount_incl_vat numeric,unallocated_excl numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH r AS(SELECT * FROM public.metrics_receipt_scope r WHERE r.paid_at>=((_scope->>'from')::date::timestamp AT TIME ZONE 'Asia/Riyadh') AND r.paid_at<(((_scope->>'to')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh')), a AS(SELECT r.id,coalesce(sum(a.amount_excl_vat),0) AS all_excl,coalesce(sum(a.vat_amount),0) AS all_vat,coalesce(sum(a.amount_excl_vat*coalesce(public.metrics_contract_factor(i.contract_id,_scope),0)),0) AS scoped_excl,coalesce(sum(a.vat_amount*coalesce(public.metrics_contract_factor(i.contract_id,_scope),0)),0) AS scoped_vat FROM r LEFT JOIN public.receipt_allocations a ON a.receipt_id=r.id AND a.reverses_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.receipt_allocations rev WHERE rev.reverses_id=a.id) LEFT JOIN public.installments i ON i.id=a.installment_id GROUP BY r.id), parts AS(SELECT r.*,a.scoped_excl,a.scoped_vat,CASE WHEN nullif(_scope->>'building','') IS NULL AND nullif(_scope->>'phase','') IS NULL AND nullif(_scope->>'activity','') IS NULL AND nullif(_scope->>'unit_type','') IS NULL THEN greatest(0,r.amount_excl_vat-a.all_excl)*CASE WHEN r.contract_id IS NULL THEN 1 ELSE coalesce(public.metrics_contract_factor(r.contract_id,_scope),0) END ELSE 0 END AS unallocated,CASE WHEN nullif(_scope->>'building','') IS NULL AND nullif(_scope->>'phase','') IS NULL AND nullif(_scope->>'activity','') IS NULL AND nullif(_scope->>'unit_type','') IS NULL THEN greatest(0,coalesce(r.vat_amount,0)-a.all_vat)*CASE WHEN r.contract_id IS NULL THEN 1 ELSE coalesce(public.metrics_contract_factor(r.contract_id,_scope),0) END ELSE 0 END AS unallocated_vat FROM r JOIN a ON a.id=r.id) SELECT id,receipt_no,paid_at,status::text,scoped_excl+unallocated,CASE WHEN vat_documented THEN scoped_vat+unallocated_vat ELSE NULL END,CASE WHEN vat_documented THEN scoped_excl+unallocated+scoped_vat+unallocated_vat ELSE NULL END,unallocated FROM parts WHERE scoped_excl+unallocated>0 OR scoped_vat+unallocated_vat>0 $$;
CREATE OR REPLACE FUNCTION public.metrics_opportunity_matches(_id uuid,_scope jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=_id AND (EXISTS(SELECT 1 FROM public.metrics_unit_scope u WHERE public.metrics_scope_match(u,_scope) AND (u.id=ANY(o.preferred_unit_ids) OR EXISTS(SELECT 1 FROM public.booking_units bu WHERE bu.booking_id=o.booking_id AND bu.unit_id=u.id))) OR ((o.preferred_unit_ids IS NULL OR cardinality(o.preferred_unit_ids)=0) AND NOT EXISTS(SELECT 1 FROM public.booking_units bu WHERE bu.booking_id=o.booking_id) AND nullif(_scope->>'building','') IS NULL AND nullif(_scope->>'phase','') IS NULL AND nullif(_scope->>'unit_type','') IS NULL AND (nullif(_scope->>'activity','') IS NULL OR o.activity_id::text=_scope->>'activity' OR (_scope->>'activity'='unassigned' AND o.activity_id IS NULL))))) $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.metrics_finance(jsonb)'::regprocedure) INTO d;d:=replace(d,'FUNCTION public.metrics_finance(','FUNCTION public._metrics_finance_base(');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.metrics_finance(_scope jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH r AS(SELECT * FROM public.metrics_collected_rows(_scope)),b AS(SELECT public._metrics_finance_base(_scope) AS data) SELECT data||jsonb_build_object('collected_excl',coalesce((SELECT sum(amount_excl_vat) FROM r),0),'collected_vat',CASE WHEN EXISTS(SELECT 1 FROM r WHERE vat_amount IS NULL) THEN NULL ELSE coalesce((SELECT sum(vat_amount) FROM r),0) END,'collected_incl',CASE WHEN EXISTS(SELECT 1 FROM r WHERE amount_incl_vat IS NULL) THEN NULL ELSE coalesce((SELECT sum(amount_incl_vat) FROM r),0) END,'unallocated_excl',coalesce((SELECT sum(unallocated_excl) FROM r),0),'due_incl',(data->>'due_excl')::numeric+(data->>'due_vat')::numeric,'overdue_incl',(data->>'overdue_excl')::numeric+(data->>'overdue_vat')::numeric,'annual_rent_incl',(data->>'annual_rent_excl_vat')::numeric+(data->>'annual_rent_vat')::numeric) FROM b $$;
CREATE OR REPLACE FUNCTION public.metrics_section(_name text,_scope jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN CASE _name WHEN 'inventory' THEN RETURN public.metrics_inventory(_scope);WHEN 'pipeline' THEN RETURN public.metrics_pipeline(_scope);WHEN 'finance' THEN RETURN public.metrics_finance(_scope);WHEN 'quality' THEN RETURN public.metrics_quality(_scope);WHEN 'approvals' THEN RETURN public.metrics_pending_approvals(_scope);ELSE RAISE EXCEPTION 'قسم غير صالح';END CASE;EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('unavailable',true,'error','تعذر تحميل القسم؛ أعد المحاولة');END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public._metrics_snapshot(jsonb,text)'::regprocedure) INTO d;d:=replace(d,'public.metrics_inventory(s)','public.metrics_section(''inventory'',s)');d:=replace(d,'public.metrics_pipeline(s)','public.metrics_section(''pipeline'',s)');d:=replace(d,'public.metrics_finance(s)','public.metrics_section(''finance'',s)');d:=replace(d,'public.metrics_quality(s)','public.metrics_section(''quality'',s)');d:=replace(d,'public.metrics_pending_approvals(s)','public.metrics_section(''approvals'',s)');EXECUTE d;END $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.metrics_drilldown(text,jsonb,integer,integer)'::regprocedure) INTO d;d:=replace(d,'FUNCTION public.metrics_drilldown(','FUNCTION public._metrics_drilldown_extended(');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.metrics_drilldown(_metric text,_scope jsonb DEFAULT '{}',_limit integer DEFAULT 25,_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE snap jsonb;s jsonb;rows jsonb;total integer;BEGIN IF _metric NOT IN('collected','published_leased','occupancy') THEN RETURN public._metrics_drilldown_extended(_metric,_scope,_limit,_offset);END IF;snap:=public.metrics_snapshot(_scope);s:=snap->'scope';IF snap->>'audience'='investor' THEN RAISE EXCEPTION 'المستثمر يعرض المجمع فقط';END IF;IF _metric='collected' THEN IF snap->'finance' IS NULL OR snap->'finance'->>'unavailable'='true' THEN RAISE EXCEPTION 'غير متاح أو غير مسموح بعرض المالية';END IF;WITH filtered AS(SELECT * FROM public.metrics_collected_rows(s)),paged AS(SELECT * FROM filtered ORDER BY paid_at DESC,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM paged p),'[]'),(SELECT count(*) FROM filtered) INTO rows,total;ELSE IF snap->>'audience' IN('control','accountant') THEN RAISE EXCEPTION 'غير مسموح بعرض الوحدات';END IF;WITH filtered AS(SELECT * FROM public.metrics_unit_scope u WHERE public.metrics_scope_match(u,s) AND publish_state='published' AND CASE WHEN _metric='published_leased' THEN leasing_status='leased' ELSE leasing_status IN('leased','on_hold','pending_contract') END),paged AS(SELECT * FROM filtered ORDER BY building_number,unit_number,id LIMIT least(greatest(_limit,1),500) OFFSET greatest(_offset,0)) SELECT coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM paged p),'[]'),(SELECT count(*) FROM filtered) INTO rows,total;END IF;RETURN jsonb_build_object('rows',rows,'count',total,'scope',s,'as_of',snap->'as_of');END $$;
REVOKE ALL ON FUNCTION public.metrics_contract_factor(uuid,jsonb),public.metrics_collected_rows(jsonb),public._metrics_finance_base(jsonb),public.metrics_section(text,jsonb),public._metrics_drilldown_extended(text,jsonb,integer,integer) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.metrics_contract_factor(uuid,jsonb),public.metrics_collected_rows(jsonb),public._metrics_finance_base(jsonb),public.metrics_section(text,jsonb),public._metrics_drilldown_extended(text,jsonb,integer,integer) TO service_role;
SELECT to_regprocedure('public.metrics_collected_rows(jsonb)') IS NOT NULL AS receipt_attribution_ready,has_function_privilege('authenticated','public.metrics_collected_rows(jsonb)','EXECUTE') AS raw_access_must_be_false;